import Foundation

/// Demo events (порт `data/FakeEventsRepository.kt`, те же данные и kk/en переводы).
enum FakeEventsRepository {
    private static func ev(
        _ n: Int, _ interest: Interest, _ title: String, _ startsAt: String, _ place: String,
        _ address: String, _ price: String?, _ url: String, _ source: String,
        city: String = "astana",
        kk: (String, String)? = nil, // (title, place) in Kazakh, for generated city templates
        en: (String, String)? = nil,
        desc: Descriptions.Text? = nil // explicit text for generated city templates
    ) -> EventCard {
        let id = city == "astana" ? "demo-\(n)" : "\(city)-\(n)"
        let d = desc ?? Descriptions.forId(id)
        return EventCard(
            id: id, cityId: city,
            titleRu: title, titleKk: kk?.0 ?? Translations.kk(title), titleEn: en?.0 ?? Translations.en(title),
            startsAt: startsAt,
            placeRu: place, placeKk: kk?.1 ?? Translations.kk(place), placeEn: en?.1 ?? Translations.en(place),
            address: address,
            interest: interest, price: price,
            whyMatches: "Интерес: \(interest.labelRu.lowercased())",
            sourceUrl: url, sourceName: source,
            workingHours: eventHours(startsAt, place, interest),
            descriptionRu: d?.ru ?? "", descriptionKk: d?.kk ?? "", descriptionEn: d?.en ?? ""
        )
    }

    private static let timeRe = try! NSRegularExpression(pattern: "(\\d{1,2}):(\\d{2})")

    private static func eventHours(_ startsAt: String, _ place: String, _ interest: Interest) -> String {
        let ns = startsAt as NSString
        let m = timeRe.matches(in: startsAt, range: NSRange(location: 0, length: ns.length)).last
        let h = m.flatMap { Int(ns.substring(with: $0.range(at: 1))) } ?? 10
        let mm = m.map { ns.substring(with: $0.range(at: 2)) } ?? "00"
        let pl = place.lowercased()
        if interest == .exhibitions || pl.contains("музей") { return "Касса 10:00–18:00, Пн — выходной" }
        if h >= 17 { return String(format: "Вход за 30 мин · %02d:%@–%02d:%@", h, mm, (h + 2) % 24, mm) }
        return String(format: "%02d:%@–%02d:%@", h, mm, (h + 3) % 24, mm)
    }

    // BEGIN GENERATED by tools/gen_feed.py
    private static func real(
        _ id: String, _ city: String, _ interest: Interest, _ isPlace: Bool,
        _ tRu: String, _ tKk: String, _ tEn: String, _ startsAt: String,
        _ pRu: String, _ pKk: String, _ pEn: String, _ address: String, _ price: String?,
        _ url: String, _ source: String, _ hours: String, _ lat: Double?, _ lon: Double?
    ) -> EventCard {
        let d = Descriptions.forId(id)
        return EventCard(
            id: id, cityId: city, titleRu: tRu, titleKk: tKk, titleEn: tEn, startsAt: startsAt,
            placeRu: pRu, placeKk: pKk, placeEn: pEn, address: address, interest: interest, price: price,
            whyMatches: "Интерес: \(interest.labelRu.lowercased())", sourceUrl: url, sourceName: source,
            isPlace: isPlace, workingHours: hours,
            descriptionRu: d?.ru ?? "", descriptionKk: d?.kk ?? "", descriptionEn: d?.en ?? "",
            lat: lat, lon: lon
        )
    }

